def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            components.append((color, cells))
    out = [[0] * w for _ in range(h)]
    components.sort(key=lambda item: max(c for r, c in item[1]), reverse=True)
    for color, cells in components:
        shift = 0
        while True:
            next_cells = [(r, c + shift + 1) for r, c in cells]
            if any(c >= w or out[r][c] != 0 for r,c in next_cells):
                break
            shift += 1
        for r, c in cells:
            out[r][c + shift] = color
    return out
